def {{fn_name}}(arr, bucket_count=10):
    if not arr: return arr
    lo, hi = min(arr), max(arr)
    if lo == hi: return list(arr)
    buckets = [[] for _ in range(bucket_count)]
    for x in arr:
        idx = min(bucket_count - 1, int((x - lo) / (hi - lo) * bucket_count))
        buckets[idx].append(x)
    out = []
    for b in buckets:
        out.extend(sorted(b))
    return out
